CREATE TABLE "project" ("id" uuid PRIMARY KEY,"code" varchar(50) NOT NULL UNIQUE,"name" varchar(200) NOT NULL,"client_name" varchar(200),"phase" varchar(100),"status" varchar(30) NOT NULL DEFAULT 'DRAFT',"startDate" date,"targetDate" date,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL);
CREATE TABLE "region" ("id" uuid PRIMARY KEY,"projectId" uuid NOT NULL REFERENCES "project"("id") ON DELETE CASCADE,"name" varchar(150) NOT NULL,UNIQUE("projectId","name"));
CREATE TABLE "site" ("id" uuid PRIMARY KEY,"projectId" uuid NOT NULL REFERENCES "project"("id") ON DELETE CASCADE,"regionId" uuid REFERENCES "region"("id") ON DELETE SET NULL,"siteCode" varchar(50) NOT NULL,"name" varchar(200) NOT NULL,"latitude" decimal(10,7),"longitude" decimal(10,7),"geofenceRadiusM" integer NOT NULL DEFAULT 100,"address" varchar(500),"city" varchar(100),"area" varchar(100),"scopeVariant" varchar(100),"status" varchar(30) NOT NULL DEFAULT 'PLANNED',UNIQUE("projectId","siteCode"));
CREATE TABLE "task_type" ("id" uuid PRIMARY KEY,"projectId" uuid NOT NULL REFERENCES "project"("id") ON DELETE CASCADE,"code" varchar(50) NOT NULL,"name" varchar(200) NOT NULL,"category" varchar(100) NOT NULL,"templateId" uuid,"order" integer NOT NULL DEFAULT 0,"isActive" boolean NOT NULL DEFAULT true,UNIQUE("projectId","code"));
CREATE TABLE "milestone" ("id" uuid PRIMARY KEY,"projectId" uuid NOT NULL REFERENCES "project"("id") ON DELETE CASCADE,"code" varchar(50) NOT NULL,"name" varchar(200) NOT NULL,"kind" varchar(20) NOT NULL,"sequence" integer NOT NULL,"targetDate" date,UNIQUE("projectId","code"));
CREATE TABLE "milestone_requirement" ("milestoneId" uuid NOT NULL REFERENCES "milestone"("id") ON DELETE CASCADE,"taskTypeId" uuid NOT NULL REFERENCES "task_type"("id") ON DELETE CASCADE,PRIMARY KEY("milestoneId","taskTypeId"));
CREATE TABLE "task" ("id" uuid PRIMARY KEY,"projectId" uuid NOT NULL REFERENCES "project"("id") ON DELETE CASCADE,"siteId" uuid NOT NULL REFERENCES "site"("id") ON DELETE CASCADE,"taskTypeId" uuid NOT NULL REFERENCES "task_type"("id"),"templateId" uuid,"title" varchar(250) NOT NULL,"status" varchar(30) NOT NULL DEFAULT 'NOT_STARTED',"assigneeId" uuid,"plannedCompletionAt" timestamptz,"actualCompletionAt" timestamptz,"currentSubmissionId" uuid,"origin" varchar(20) NOT NULL,"createdBy" uuid NOT NULL);
CREATE INDEX "task_projectId_status_idx" ON "task"("projectId","status"); CREATE INDEX "task_siteId_idx" ON "task"("siteId"); CREATE UNIQUE INDEX "planned_task_per_site_type" ON "task"("siteId","taskTypeId") WHERE "origin"='PLANNED';
